using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using PollObject;

namespace InformationWeb.Pages.Poll2
{
    public partial class QuestionList : PageBase
    {
        private const int FIXED_POLL_PART_ID = 56;

        #region Properties

        protected DCore.SessionUser CurrentUser
        {
            get { return Session[Globals.USER] as DCore.SessionUser; }
        }

        protected CommonControls.MessageBox.MessageBox MsgBox
        {
            get
            {
                if (Master == null)
                    return null;

                Control objControl = FindControlRecursive(Master, "MsgBox");
                return objControl as CommonControls.MessageBox.MessageBox;
            }
        }

        #endregion

        #region Page Events

        protected void Page_Load(object sender, EventArgs e)
        {
            if (CurrentUser == null)
            {
                Response.Redirect("~/dang-nhap.html");
                return;
            }

            if (!IsPostBack)
            {
                txtPollPartID.Text = FIXED_POLL_PART_ID.ToString();
                hidEditPollPartID.Value = FIXED_POLL_PART_ID.ToString();
                txtEditPollPartID.Text = FIXED_POLL_PART_ID.ToString();
                BindGrid(0);
            }
        }

        #endregion

        #region Helpers

        private Control FindControlRecursive(Control objRoot, string strId)
        {
            if (objRoot == null)
                return null;

            if (objRoot.ID == strId)
                return objRoot;

            foreach (Control objChild in objRoot.Controls)
            {
                Control objFound = FindControlRecursive(objChild, strId);
                if (objFound != null)
                    return objFound;
            }

            return null;
        }

        private int GetQuestionID()
        {
            int intQuestionID = 0;
            int.TryParse(hidQuestionID.Value, out intQuestionID);
            return intQuestionID;
        }

        private string GetQuestionNameText()
        {
            return HttpUtility.HtmlDecode(txtQuestionName.Text.Trim());
        }

        #endregion

        #region Data

        private POL_Plan CreateDataObject()
        {
            return new POL_Plan();
        }

        private void BindGrid(int intPage)
        {
            try
            {
                POL_Plan obj = CreateDataObject();
                DataTable dtb = obj.GetDataTable("POL_Question_SearchForManage",
                    "@PollPartID", FIXED_POLL_PART_ID,
                    "@KeyWord", txtSearch.Text.Trim());

                grvData.DataSource = dtb;
                grvData.PageIndex = intPage;
                grvData.DataBind();
                udpList.Update();
            }
            catch (Exception)
            {
                ShowError("Không tải được danh sách câu hỏi. Kiểm tra đã chạy script POL_Question_Manage.sql chưa.");
            }
        }

        private void ResetEditForm()
        {
            hidQuestionID.Value = "0";
            hidEditPollPartID.Value = FIXED_POLL_PART_ID.ToString();
            txtEditPollPartID.Text = FIXED_POLL_PART_ID.ToString();
            txtQuestionCode.Text = "";
            txtQuestionName.Text = "";
            txtOrderIndex.Text = "";
            litPreview.Text = "";
        }

        private void LoadEditForm(int intQuestionID)
        {
            ResetEditForm();

            if (intQuestionID > 0)
            {
                POL_Plan obj = CreateDataObject();
                DataTable dtb = obj.GetDataTable("POL_Question_Get", "@QuestionID", intQuestionID);

                if (dtb == null || dtb.Rows.Count == 0)
                {
                    ShowWarning("Không tìm thấy câu hỏi!");
                    return;
                }

                DataRow dr = dtb.Rows[0];
                hidQuestionID.Value = dr["QuestionID"].ToString();
                txtQuestionCode.Text = dr["QuestionCode"].ToString();
                txtQuestionName.Text = dr["QuestionName"].ToString();
                txtOrderIndex.Text = dr["OrderIndex"].ToString();
                litPreview.Text = dr["QuestionName"].ToString();
                lblTitle.Text = "Cập nhật câu hỏi";
            }
            else
            {
                lblTitle.Text = "Thêm câu hỏi mới";
            }

            udpEdit.Update();
            ShowModal();
        }

        private void ShowModal()
        {
            string strKey = String.Format("_OpenPollQuestionModal_{0}", DateTime.Now.Ticks);
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), strKey, "PollQuestion_ShowModal();", true);
        }

        private void HideModal()
        {
            string strKey = String.Format("_ClosePollQuestionModal_{0}", DateTime.Now.Ticks);
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), strKey, "PollQuestion_HideModal();", true);
        }

        private bool ValidateForm()
        {
            if (txtQuestionCode.Text.Trim() == "")
            {
                ShowWarning("Vui lòng nhập mã câu hỏi (QuestionCode)!");
                return false;
            }

            if (GetQuestionNameText() == "")
            {
                ShowWarning("Vui lòng nhập nội dung câu hỏi (QuestionName)!");
                return false;
            }

            return true;
        }

        private bool SaveData()
        {
            POL_Plan obj = CreateDataObject();
            int intQuestionID = GetQuestionID();
            string strUserName = CurrentUser != null ? CurrentUser.UserName : "system";
            string strQuestionName = GetQuestionNameText();
            txtQuestionName.Text = strQuestionName;

            try
            {
                if (intQuestionID <= 0)
                {
                    DataTable dtb = obj.GetDataTable("POL_Question_Add",
                        "@QuestionCode", txtQuestionCode.Text.Trim(),
                        "@QuestionName", strQuestionName,
                        "@PollPartID", FIXED_POLL_PART_ID,
                        "@CreatedUser", strUserName);

                    if (dtb == null || dtb.Rows.Count == 0)
                    {
                        ShowError("Không thêm được câu hỏi. Vui lòng thử lại!");
                        return false;
                    }

                    txtOrderIndex.Text = dtb.Rows[0]["OrderIndex"].ToString();
                }
                else
                {
                    DataTable dtb = obj.GetDataTable("POL_Question_Update",
                        "@QuestionID", intQuestionID,
                        "@QuestionCode", txtQuestionCode.Text.Trim(),
                        "@QuestionName", strQuestionName,
                        "@UpdatedUser", strUserName);

                    if (dtb == null || dtb.Rows.Count == 0 || Convert.ToInt32(dtb.Rows[0]["AffectedRows"]) <= 0)
                    {
                        ShowError("Không cập nhật được câu hỏi. Vui lòng thử lại!");
                        return false;
                    }
                }

                return true;
            }
            catch (Exception)
            {
                ShowError("Lỗi lưu dữ liệu. Vui lòng thử lại sau!");
                return false;
            }
        }

        private void DeleteQuestion(int intQuestionID)
        {
            try
            {
                POL_Plan obj = CreateDataObject();
                DataTable dtb = obj.GetDataTable("POL_Question_Delete", "@QuestionID", intQuestionID);

                if (dtb == null || dtb.Rows.Count == 0 || Convert.ToInt32(dtb.Rows[0]["AffectedRows"]) <= 0)
                {
                    ShowWarning("Không xóa được câu hỏi!");
                    return;
                }

                BindGrid(grvData.PageIndex);
            }
            catch (Exception)
            {
                ShowError("Lỗi xóa dữ liệu. Vui lòng thử lại sau!");
            }
        }

        private void ShowWarning(string strMessage)
        {
            if (MsgBox != null)
                MsgBox.ShowWarning(strMessage);
        }

        private void ShowError(string strMessage)
        {
            if (MsgBox != null)
                MsgBox.ShowError(strMessage);
        }

        #endregion

        #region Control Events

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            BindGrid(0);
        }

        protected void btnAddNew_Click(object sender, EventArgs e)
        {
            LoadEditForm(0);
        }

        protected void grvData_PageIndexChanging(object sender, GridViewPageEventArgs e)
        {
            BindGrid(e.NewPageIndex);
        }

        protected void grvData_RowCommand(object sender, GridViewCommandEventArgs e)
        {
            int intQuestionID = Convert.ToInt32(e.CommandArgument);

            if (e.CommandName == "EditItem")
            {
                LoadEditForm(intQuestionID);
            }
            else if (e.CommandName == "DeleteItem")
            {
                DeleteQuestion(intQuestionID);
            }
        }

        protected void btnSave_Click(object sender, EventArgs e)
        {
            try
            {
                if (!ValidateForm())
                {
                    udpEdit.Update();
                    ShowModal();
                    return;
                }

                if (SaveData())
                {
                    HideModal();
                    BindGrid(grvData.PageIndex);
                }
                else
                {
                    udpEdit.Update();
                    ShowModal();
                }
            }
            catch (Exception)
            {
                ShowError("Lỗi xử lý khi lưu. Kiểm tra nội dung HTML hoặc script POL_Question_Manage.sql trên DB.");
                udpEdit.Update();
                ShowModal();
            }
        }

        protected void btnPreview_Click(object sender, EventArgs e)
        {
            string strQuestionName = GetQuestionNameText();
            txtQuestionName.Text = strQuestionName;
            litPreview.Text = strQuestionName;
            udpEdit.Update();
            ShowModal();
        }

        #endregion
    }
}

